def process_graph(graph_data):
    graph_copy = graph_data.copy()
    # Find the chassis node
    chassis_node = None
    for node in graph_copy.nodes(data=True):
        if node[0].startswith('ju1.a1.m4') and 'EK_CHASSIS' in node[1]['type']:
            chassis_node = node[0]
            break

    if not chassis_node:
        return {'type': 'text', 'data': 'Chassis node not found.', 'updated_graph': nx.readwrite.json_graph.node_link_data(graph_copy)}

    # Add new packet switch node
    new_packet_switch_name = 'new_EK_PACKET_SWITCH_96'
    graph_copy.add_node(new_packet_switch_name, name=new_packet_switch_name, type=['EK_PACKET_SWITCH'])
    graph_copy.add_edge(chassis_node, new_packet_switch_name, type='RK_CONTAINS')

    # Calculate total physical capacity for each direct child node of chassis
    children_nodes = []
    for child in graph_copy.successors(chassis_node):
        if 'EK_PACKET_SWITCH' in graph_copy.nodes[child]['type']:
            total_capacity = 0
            for port in graph_copy.successors(child):
                if 'EK_PORT' in graph_copy.nodes[port]['type']:
                    total_capacity += graph_copy.nodes[port].get('physical_capacity_bps', 0)
            children_nodes.append((child, total_capacity))

    # Sort children nodes based on total physical capacity
    sorted_children = sorted(children_nodes, key=lambda x: x[1], reverse=True)

    return {'type': 'list', 'data': sorted_children, 'updated_graph': nx.readwrite.json_graph.node_link_data(graph_copy)}
